/*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsmomListMapper :  댓글상담실(조회수)*/
UPDATE AYE100 SET
    RDCNT_NOCS = NVL(TO_NUMBER(RDCNT_NOCS), 0) +1
WHERE 1=1
AND BBSCTT_TYPE_SE_CD = '08'
AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO}

mapper.insert:
    /*
     * SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsRplyListMapper :  댓글상담실(등록)
     * 2023.04.27 수정 : 불필요한 컬럼 삭제 / 컬럼 추가 - Jeong.Won.Je
     */


				SELECT AYE100_SQ01.CURRVAL AS BBSCTT_ESNTAL_NO
				FROM DUAL 


			INSERT INTO AYE100 (
					  BBSCTT_ESNTAL_NO         /* 게시글번호 */
					, BBSCTT_TYPE_SE_CD        /* 게시글구분코드 */

					, BBSCTT_TTL_NM            /* 게시글제목명 */


					, WRTR_NM_ENCPT            /* 작성자명 */


					, HPGE_URL_ADDR            /* 홈페이지URL */


					, BRTH_YMD                 /* 출생일자 */


					, EML_ADDR_ENCPT           /* 이메일주소 */


					, CNTN_IP_ADDR             /* 아이피주소 */


					, BBSCTT_CN                /* 게시글내용 */


					, SXDC_SE_CD               /* 성별 */


					, ACBG_SE_CD               /* 학력구분코드 */


					, GRADE_SE_CD              /* 학년구분코드 */


                    , GRDTN_STTS_SE_CD         /* 졸업상태구분코드 */


                    , REAL_CONSTT_SE_CD        /* 실제상담자구분코드 */


                    , REAL_CONSTT_ETC_CN       /* 실제상담자기타내용 */


                    , YNGBGS_SE_NO             /* 청소년구분번호 */


                    , PROBM_STTS_LCLAS_SE_CD   /* 문제상태대분류구분코드 */


                    , PROBM_STTS_MLSFC_SE_CD   /* 문제상태중분류구분코드 */


                    , PROBM_STTS_SCLAS_SE_CD   /* 문제상태소분류구분코드 */


                    , PROBM_CAS_LCLAS_SE_CD    /* 문제원인대분류구분코드 */


                    , PROBM_CAS_SCLAS_SE_CD    /* 문제원인소분류구분코드 */


                    , ETC_CN                   /* 기타내용 */


                    , LINK_PRCS_SE_CN          /* 연계처리구분내용 */


                    , RCPT_RQST_COURS_SE_CD    /* 접수의뢰경로구분코드 */


                    , LINK_INST_NM             /* 연계기관명 */

					, FRST_REG_DT              /* 최초등록일자 */
					, FRST_RGTR_ID             /* 최초등록아이디 */
					)
			VALUES(
					AYE100_SQ01.NEXTVAL
					, '08' 

					, #{BBSCTT_TTL_NM}


					, C##RG.ENC_B64(#{WRTR_NM_ENCPT}) 


                    , #{HPGE_URL_ADDR}


					, #{BRTH_YMD}


					, #{EML_ADDR_ENCPT} 


					, #{CNTN_IP_ADDR}


					, #{BBSCTT_CN} 


					, #{SXDC_SE_CD}


                    , #{ACBG_SE_CD}


                    , #{GRADE_SE_CD}


                    , #{GRDTN_STTS_SE_CD}


                    , #{REAL_CONSTT_SE_CD}


                    , #{REAL_CONSTT_ETC_CN}


                    , #{YNGBGS_SE_NO}


                    , #{PROBM_STTS_LCLAS_SE_CD}


                    , #{PROBM_STTS_MLSFC_SE_CD}


                    , #{PROBM_STTS_SCLAS_SE_CD}


                    , #{PROBM_CAS_LCLAS_SE_CD}


                    , #{PROBM_CAS_SCLAS_SE_CD}


                    , #{ETC_CN}


                    , #{LINK_PRCS_SE_CN}


                    , #{RCPT_RQST_COURS_SE_CD}


                    , #{LINK_INST_NM}

					, TO_DATE(#{FRST_REG_DT},'YYYY-MM-DD')
					, #{FRST_RGTR_ID}
					)

