/* * SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsRplyListMapper : 댓글상담실(수정) * 2023.04.27 수정 : 불필요한 컬럼 삭제 / 컬럼 추가 - Jeong.Won.Je */ UPDATE AYE100 SET SXDC_SE_CD = #{SXDC_SE_CD} /* 성별 */ , BBSCTT_TTL_NM = #{BBSCTT_TTL_NM} /* 게시글제목명 */ , WRTR_NM_ENCPT = C##RG.ENC_B64(#{WRTR_NM_ENCPT}) /* 작성자명암호화 */
, BBSCTT_CN = #{BBSCTT_CN} /* 게시글내용 */
, ACBG_SE_CD = #{ACBG_SE_CD} /* 학력구분코드 */ , GRADE_SE_CD = #{GRADE_SE_CD} /* 학년구분코드 */ , GRDTN_STTS_SE_CD = #{GRDTN_STTS_SE_CD} /* 졸업상태구분코드 */ , REAL_CONSTT_SE_CD = #{REAL_CONSTT_SE_CD} /* 실제상담자구분코드 */ , REAL_CONSTT_ETC_CN = #{REAL_CONSTT_ETC_CN} /* 실제상담자기타내용 */ , YNGBGS_SE_NO = #{YNGBGS_SE_NO} /* 청소년구분번호 */ , PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD} /* 문제상태대분류 */ , PROBM_STTS_MLSFC_SE_CD = #{PROBM_STTS_MLSFC_SE_CD} /* 문제상태중분류 */ , PROBM_STTS_SCLAS_SE_CD = #{PROBM_STTS_SCLAS_SE_CD} /* 문제상태소분류 */ , PROBM_CAS_LCLAS_SE_CD = #{PROBM_CAS_LCLAS_SE_CD} /* 문제원인대분류 */ , PROBM_CAS_SCLAS_SE_CD = #{PROBM_CAS_SCLAS_SE_CD} /* 문제원인소분류 */ , ETC_CN = #{ETC_CN} /* 문제상세 */ , LINK_PRCS_SE_CN = #{LINK_PRCS_SE_CN} /* 연계처리구분내용 */ , RCPT_RQST_COURS_SE_CD = #{RCPT_RQST_COURS_SE_CD} /* 접수의뢰경로구분코드 */ , LINK_INST_NM = #{LINK_INST_NM} /* 연계기관명 */ , LAST_MDFR_ID = #{LAST_MDFR_ID} /* 최종수정아이디 */ , LAST_MDFCN_DT = SYSDATE /* 최종수정일 */ WHERE 1=1 AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO} AND BBSCTT_TYPE_SE_CD = #{BBSCTT_TYPE_SE_CD}

UPDATE AYE110 SET   /*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsRplyListMapper :  댓글상담실(댓글삭제)*/
              DEL_YN = 'Y'
            , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '08'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
    AND     CMNT_ESNTAL_NO = #{CMNT_ESNTAL_NO__origin}


    /*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsRplyListMapper :  댓글상담실(조회수)
